3	namespace App\Http\Controllers\Api\Professional\Uploads;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\ResolveCurrentProfessional;
7	use App\Http\Controllers\Concerns\ResolveCurrentSite;
8	use App\Http\Requests\Api\Professional\Uploads\ReorderBrandPlaceholdersRequest;
9	use App\Http\Requests\Api\Professional\Uploads\ReorderPoolImagesRequest;
10	use App\Http\Requests\Api\Professional\Uploads\UploadBrandLogoRequest;
11	use App\Http\Requests\Api\Professional\Uploads\UploadBrandPlaceholderImageRequest;
12	use App\Http\Requests\Api\Professional\Uploads\UploadImageRequest;
13	use App\Jobs\DeleteMediaArtifactsJob;
14	use App\Jobs\ProcessImageVariantsJob;
15	use App\Jobs\ProcessVideoVariantsJob;
16	use App\Models\Core\Site\SiteMedia;
17	use App\Services\Cache\SiteCacheService;
18	use App\Services\Media\BrandDesignMediaService;
19	use App\Services\Media\ImageVariantService;
20	use App\Services\Professional\ConfirmationPreferenceService;
21	use Illuminate\Http\JsonResponse;
22	use Illuminate\Http\Request;
23	use Illuminate\Support\Facades\DB;
24	use Illuminate\Support\Facades\Log;
25	use Illuminate\Support\Facades\Storage;
26	use Illuminate\Support\Str;
27	use Throwable;
28	
29	// V2: Media management (images, videos, brand logos, placeholders). Handles upload → processing pipeline → R2 storage.
30	class ProfessionalUploadController extends ApiController
31	{
32	    use ResolveCurrentProfessional;
33	    use ResolveCurrentSite;
34	
35	    public function __construct(
36	        private readonly ImageVariantService $mediaService,
37	        private readonly BrandDesignMediaService $brandDesign,
38	    ) {}
39	
40	    /**
41	     * Upload an image or video to a pool (gallery or content).
42	     *
43	     * Accepts exactly one of: `image` (JPEG/PNG/WebP) or `video` (MP4/MOV/WebM).
44	     * Returns immediately; processing runs async on the appropriate queue.
45	     *
46	     * POST /api/uploads
47	     *   { pool: gallery|content, image?: <file>, video?: <file>, alt_text?: string }
48	     */
49	    public function upload(UploadImageRequest $request): JsonResponse
50	    {
51	        $pro = $this->currentProfessional($request);
52	        $pro->loadMissing('site');
53	        $site = $this->currentSite($pro);
54	
55	        $pool = $request->validated('pool');
56	        $isVideo = $request->hasFile('video');
57	        $file = $isVideo ? $request->file('video') : $request->file('image');
58	        $mediaType = $isVideo ? SiteMedia::MEDIA_TYPE_VIDEO : SiteMedia::MEDIA_TYPE_IMAGE;
59	
60	        Log::info('Media upload started', [
61	            'pro_id' => $pro->id,
62	            'site_id' => $site->id,
63	            'pool' => $pool,
64	            'media_type' => $mediaType,
65	            'file_size_kb' => $file->getSize() / 1024,
66	        ]);
67	
68	        // Pool limit is shared across media types (images + videos count toward the same cap).
69	        $maxItems = (int) config("sidest.image_pools.{$pool}.max", 5);
70	
71	        $activeCount = SiteMedia::query()
72	            ->where('site_id', $site->id)
73	            ->where('pool', $pool)
74	            ->where('is_active', true)
75	            ->count();
76	
77	        if ($activeCount >= $maxItems) {
78	            return $this->error(
79	                ucfirst($pool)." media limit reached (max {$maxItems}).", 422
80	            );
81	        }
82	
83	        // --- Create SiteMedia row (with advisory lock for race safety) ---
84	        $media = DB::transaction(function () use ($site, $pool, $maxItems, $request, $mediaType, $file) {
85	            if (DB::getDriverName() === 'pgsql') {
86	                DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-images:{$site->id}"]);
87	            }
88	
89	            $siteImages = SiteMedia::query()
90	                ->where('site_id', $site->id)
91	                ->lockForUpdate()
92	                ->get(['id', 'pool', 'sort_order', 'is_active']);
93	
94	            $activeCount = $siteImages
95	                ->where('pool', $pool)
96	                ->where('is_active', true)
97	                ->count();
98	
99	            if ($activeCount >= $maxItems) {
100	                abort(422, ucfirst($pool)." media limit reached (max {$maxItems}).");
101	            }
102	
103	            $maxSort = $siteImages->max('sort_order');
104	
105	            $media = SiteMedia::create([
106	                'site_id' => $site->id,
107	                'pool' => $pool,
108	                'path' => '',
109	                'alt_text' => $request->validated('alt_text'),
110	                'caption' => $this->normaliseOptionalString($request->validated('caption')),
111	                'sort_order' => is_null($maxSort) ? 0 : ((int) $maxSort + 1),
112	                'is_active' => true,
113	                'media_type' => $mediaType,
114	                'processing_state' => SiteMedia::PROCESSING_STATE_PENDING,
115	                'original_mime' => $file->getMimeType(),
116	                'original_size_bytes' => $file->getSize(),
117	            ]);
118	
119	            Log::info('SiteMedia row created', ['media_id' => $media->id, 'media_type' => $mediaType]);
120	
121	            return $media;
122	        });
123	
124	        // --- Store original on media disk ---
125	        $basePath = $isVideo
126	            ? "videos/{$pro->id}/{$media->id}"
127	            : "images/{$pro->id}/{$media->id}";
128	
129	        try {
130	            $mediaDisk = $this->mediaService->resolvedDiskName();
131	
132	            Log::info('Storing original to media disk', [
133	                'media_id' => $media->id,
134	                'base_path' => $basePath,
135	                'media_disk' => $mediaDisk,
136	            ]);
137	
138	            if ($isVideo) {
139	                // Stream large video files to avoid loading full content into memory.
140	                $ext = $this->mediaService->safeExtension($file->getClientOriginalExtension() ?? '', 'mp4');
141	                $hash = substr(hash_file('sha256', $file->getRealPath()), 0, 16);
142	                $path = "{$basePath}/original_{$hash}.{$ext}";
143	                $stream = fopen($file->getRealPath(), 'rb');
144	                Storage::disk($mediaDisk)->put($path, $stream, 'public');
145	                if (is_resource($stream)) {
146	                    fclose($stream);
147	                }
148	                $originalPath = $path;
149	            } else {
150	                $originalPath = $this->mediaService->storeOriginal($file, $basePath);
151	            }
152	
153	            Log::info('Original stored successfully', ['media_id' => $media->id, 'path' => $originalPath]);
154	        } catch (\Exception $e) {
155	            Log::error('Failed to store original', [
156	                'media_id' => $media->id,
157	                'error' => $e->getMessage(),
158	            ]);
159	            $media->delete();
160	
161	            return $this->error('Failed to store file: '.$e->getMessage(), 500);
162	        }
163	
164	        $media->update(['path' => $originalPath]);
165	
166	        // --- Dispatch processing job ---
167	        if ($isVideo) {
168	            try {
169	                $this->dispatchVideoJob($media->id, $originalPath, $basePath);
170	            } catch (Throwable $e) {
171	                Log::error('Video upload dispatch failed; rolling back media item.', [
172	                    'site_id' => $site->id,
173	                    'media_id' => $media->id,
174	                    'pool' => $pool,
175	                    'error' => $e->getMessage(),
176	                    'exception' => get_class($e),
177	                ]);
178	
179	                $mediaDisk = $this->mediaService->resolvedDiskName();
180	                try {
181	                    Storage::disk($mediaDisk)->delete($originalPath);
182	                } catch (Throwable $cleanupError) {
183	                    Log::warning('Failed to cleanup original video after dispatch failure.', [
184	                        'site_id' => $site->id,
185	                        'media_id' => $media->id,
186	                        'pool' => $pool,
187	                        'path' => $originalPath,
188	                        'media_disk' => $mediaDisk,
189	                        'error' => $cleanupError->getMessage(),
190	                    ]);
191	                }
192	
193	                $media->delete();
194	                app(SiteCacheService::class)->invalidateSite($site);
195	
196	                return $this->error(
197	                    'Video processing is temporarily unavailable. Please try again.',
198	                    503
199	                );
200	            }
201	        } else {
202	            $this->dispatchImageJob($media->id, $originalPath, $basePath);
203	        }
204	
205	        app(SiteCacheService::class)->invalidateSite($site);
206	
207	        // Refresh model state (sync mode may have updated processing_state to 'ready').
208	        $media->refresh();
209	        $media->load('mediaVariants');
210	        $payload = $this->buildMediaPayload($media, includeVariants: true);
211	
212	        return $this->success($payload, 201);
213	    }
214	
215	    /**
216	     * List media for the authenticated professional.
217	     *
218	     * GET /api/images
219	     *   ?pool=gallery|content          optional pool filter
220	     *   ?media_type=image|video|all    default: image (backward-compatible)
221	     *   ?ids[]=uuid,...                optional: return only specific media items (for polling)
222	     */
223	    public function index(): JsonResponse
224	    {
225	        $pro = $this->currentProfessional(request());
226	        $pro->loadMissing('site');
227	        $site = $this->currentSite($pro);
228	
229	        $rawMediaType = strtolower(trim((string) request()->input('media_type', 'image')));
230	        $mediaTypeFilter = in_array($rawMediaType, ['image', 'video', 'all'], true) ? $rawMediaType : 'image';
231	
232	        $query = SiteMedia::query()
233	            ->where('site_id', $site->id)
234	            ->where('is_active', true)
235	            ->orderBy('pool')
236	            ->orderBy('sort_order')
237	            ->orderBy('created_at');
238	
239	        if ($mediaTypeFilter !== 'all') {
240	            $query->where('media_type', $mediaTypeFilter);
241	        }
242	
243	        if (request()->has('pool')) {
244	            $pool = strtolower(trim(request()->input('pool')));
245	            if (in_array($pool, ['gallery', 'content'], true)) {
246	                $query->where('pool', $pool);
247	            }
248	        }
249	
250	        // Efficient polling: return only the requested IDs.
251	        if (request()->has('ids')) {
252	            $ids = array_filter((array) request()->input('ids'), fn ($id) => is_string($id) && Str::isUuid($id));
253	            if (! empty($ids)) {
254	                $query->whereIn('id', array_values($ids));
255	            }
256	        }
257	
258	        $query->with('mediaVariants');
259	
260	        $items = $query->get()->map(fn (SiteMedia $item) => $this->buildMediaPayload($item, includeVariants: true));
261	
262	        return $this->success([
263	            'images' => $items,
264	            'limits' => [
265	                'gallery' => config('sidest.image_pools.gallery.max', 5),
266	                'content' => config('sidest.image_pools.content.max', 5),
267	            ],
268	        ]);
269	    }
270	
271	    /**
272	     * Reorder active media for a specific pool.
273	     *
274	     * POST /api/images/reorder
275	     *   { pool: gallery|content, media_type?: image|video, ids: [uuid, ...] }
276	     *
277	     * Scope is pool + optional media_type:
278	     *   - `media_type` provided → reorder only items of that type (legacy
279	     *     behaviour; kept so Content panel's image-only + video-only reorders
280	     *     still work).
281	     *   - `media_type` omitted → reorder the *entire pool* across media types.
282	     *     Required for the unified affiliate gallery grid where photos and
283	     *     videos share one ordered list of 6 slots.
284	     */
285	    public function reorder(ReorderPoolImagesRequest $request): JsonResponse
286	    {
287	        $pro = $this->currentProfessional($request);
288	        $pro->loadMissing('site');
289	        $site = $this->currentSite($pro);
290	
291	        $pool = $request->validated('pool');
292	        // null here = mixed-type reorder (unified grid). Don't default to
293	        // 'image' — that silently drops video ids and corrupts the order.
294	        $mediaType = $request->validated('media_type');
295	        $ids = array_values(array_unique($request->validated('ids') ?? []));
296	
297	        DB::transaction(function () use ($site, $pool, $mediaType, $ids) {
298	            if (DB::getDriverName() === 'pgsql') {
299	                DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-images:{$site->id}"]);
300	            }
301	
302	            $siteImages = SiteMedia::query()
303	                ->where('site_id', $site->id)
304	                ->lockForUpdate()
305	                ->orderBy('sort_order')
306	                ->orderBy('created_at')
307	                ->get(['id', 'pool', 'media_type', 'sort_order', 'is_active']);
308	
309	            $targetImages = $siteImages
310	                ->where('is_active', true)
311	                ->where('pool', $pool)
312	                ->when($mediaType !== null, fn ($c) => $c->where('media_type', $mediaType))
313	                ->values();
314	
315	            if ($targetImages->isEmpty()) {
316	                abort(422, 'No active media found in this pool.');
317	            }
318	
319	            $targetIds = $targetImages->pluck('id')->all();
320	            $targetSet = array_flip($targetIds);
321	
322	            foreach ($ids as $id) {
323	                if (! isset($targetSet[$id])) {
324	                    abort(422, 'One or more media items are invalid.');
325	                }
326	            }
327	
328	            $remainingTargetIds = array_values(array_diff($targetIds, $ids));
329	            $reorderedTargetIds = array_merge($ids, $remainingTargetIds);
330	
331	            $finalIds = $siteImages->pluck('id')->all();
332	            $targetPositions = [];
333	
334	            foreach ($siteImages as $index => $image) {
335	                $matchesPool = $image->is_active && $image->pool === $pool;
336	                $matchesType = $mediaType === null || $image->media_type === $mediaType;
337	                if ($matchesPool && $matchesType) {
338	                    $targetPositions[] = $index;
339	                }
340	            }
341	
342	            foreach ($targetPositions as $index => $position) {
343	                $finalIds[$position] = $reorderedTargetIds[$index];
344	            }
345	
346	            $offset = $siteImages->count() + 1000;
347	
348	            foreach ($finalIds as $index => $id) {
349	                SiteMedia::query()
350	                    ->where('site_id', $site->id)
351	                    ->where('id', $id)
352	                    ->update(['sort_order' => $offset + $index]);
353	            }
354	
355	            foreach ($finalIds as $index => $id) {
356	                SiteMedia::query()
357	                    ->where('site_id', $site->id)
358	                    ->where('id', $id)
359	                    ->update(['sort_order' => $index]);
360	            }
361	        });
362	
363	        app(SiteCacheService::class)->invalidateSite($site);
364	
365	        return $this->success(['ok' => true]);
366	    }
