681	    /**
682	     * Build a media item payload array suitable for API responses.
683	     *
684	     * @param  bool  $includeVariants  Whether to include resolved variant/stream maps.
685	     * @return array<string, mixed>
686	     */
687	    private function buildMediaPayload(SiteMedia $media, bool $includeVariants = false): array
688	    {
689	        $isVideo = $media->media_type === SiteMedia::MEDIA_TYPE_VIDEO;
690	        $isReady = $media->processing_state === SiteMedia::PROCESSING_STATE_READY;
691	        $isProcessing = $media->processing_state === SiteMedia::PROCESSING_STATE_PENDING
692	            || $media->processing_state === SiteMedia::PROCESSING_STATE_PROCESSING;
693	
694	        $payload = [
695	            'id' => $media->id,
696	            'pool' => $media->pool,
697	            'alt_text' => $media->alt_text,
698	            'caption' => $media->caption,
699	            'sort_order' => $media->sort_order,
700	            'media_type' => $media->media_type,
701	            'processing_state' => $media->processing_state,
702	            'processing' => $isProcessing, // backward-compat boolean
703	            'processing_error' => $media->processing_error,
704	            'created_at' => $media->created_at,
705	            'updated_at' => $media->updated_at,
706	        ];
707	
708	        if ($isVideo) {
709	            $payload['duration_ms'] = $media->duration_ms;
710	            $payload['poster'] = null;
711	        }
712	
713	        if (! $includeVariants) {
714	            return $payload;
715	        }
716	
717	        if ($isVideo) {
718	            if ($isReady) {
719	                $mvList = $media->relationLoaded('mediaVariants')
720	                    ? $media->mediaVariants
721	                    : $media->mediaVariants()->get();
722	
723	                $variants = [];
724	                $streams = [];
725	                $poster = null;
726	
727	                foreach ($mvList as $mv) {
728	                    if ($mv->artifact_type === 'mp4') {
729	                        $variants[$mv->variant_key] = $mv->url;
730	                    } elseif ($mv->artifact_type === 'hls_playlist') {
731	                        $streams[$mv->variant_key] = $mv->url;
732	                    } elseif ($mv->artifact_type === 'poster') {
733	                        $poster = $mv->url;
734	                    }
735	                }
736	
737	                $payload['variants'] = $variants;
738	                $payload['streams'] = $streams;
739	                $payload['poster'] = $poster;
740	            } else {
741	                $payload['variants'] = [];
742	                $payload['streams'] = [];
743	                $payload['poster'] = null;
744	            }
745	        } else {
746	            $payload['variants'] = $isReady ? $media->variantUrls() : [];
747	        }
748	
749	        return $payload;
750	    }
751	}
