4	
5	use App\Models\Core\Site\SiteMedia;
6	use App\Services\Media\VideoVariantService;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldQueue;
9	use Illuminate\Foundation\Bus\Dispatchable;
10	use Illuminate\Queue\InteractsWithQueue;
11	use Illuminate\Queue\SerializesModels;
12	use Illuminate\Support\Facades\Log;
13	use Illuminate\Support\Facades\Storage;
14	use Throwable;
15	
16	/**
17	 * Transcodes a video upload into MP4 + HLS variants and a poster image.
18	 *
19	 * Dispatched onto the dedicated "videos" queue (redis_video connection)
20	 * so transcoding never contends with image processing or HTTP workers.
21	 *
22	 * State transitions:
23	 *   pending → processing (job starts)
24	 *   processing → ready   (all artifacts stored)
25	 *   processing → failed  (unrecoverable error after all retries)
26	 *
27	 * Worker invocation:
28	 *   php artisan queue:work redis_video --queue=videos --timeout=3600
29	 */
30	// V2: Transcodes video to MP4 + HLS variants with poster. Feature-flagged. Uses dedicated redis_video connection. Queue: videos.
31	class ProcessVideoVariantsJob implements ShouldQueue
32	{
33	    use Dispatchable, InteractsWithQueue, Queueable, SerializesModels;
34	
35	    public int $tries = 2;
36	
37	    public int $backoff = 60;
38	
39	    /**
40	     * @param  string  $mediaId  UUID of the SiteMedia row.
41	     * @param  string  $originalPath  Storage path of the uploaded original.
42	     * @param  string  $basePath  Directory prefix under media disk (videos/{proId}/{mediaId}).
43	     */
44	    public function __construct(
45	        public readonly string $mediaId,
46	        public readonly string $originalPath,
47	        public readonly string $basePath,
48	    ) {
49	        $this->onConnection((string) config('sidest.video_queue.connection', 'redis_video'));
50	        $this->onQueue((string) config('sidest.video_queue.name', 'videos'));
51	    }
52	
53	    public function handle(VideoVariantService $service): void
54	    {
55	        Log::info('ProcessVideoVariantsJob: starting', [
56	            'media_id' => $this->mediaId,
57	            'original_path' => $this->originalPath,
58	        ]);
59	
60	        $siteMedia = SiteMedia::withTrashed()->find($this->mediaId);
61	
62	        if (! $siteMedia) {
63	            Log::warning('ProcessVideoVariantsJob: SiteMedia row no longer exists, skipping.', [
64	                'media_id' => $this->mediaId,
65	            ]);
66	
67	            return;
68	        }
69	
70	        if ($siteMedia->trashed()) {
71	            Log::info('ProcessVideoVariantsJob: SiteMedia row is soft-deleted, skipping.', [
72	                'media_id' => $this->mediaId,
73	            ]);
74	
75	            return;
76	        }
77	
78	        SiteMedia::query()
79	            ->where('id', $this->mediaId)
80	            ->whereNull('deleted_at')
81	            ->update([
82	                'processing_state' => SiteMedia::PROCESSING_STATE_PROCESSING,
83	                'processing_error' => null,
84	            ]);
85	
86	        $diskName = $service->resolvedDiskName();
87	        $disk = Storage::disk($diskName);
88	
89	        if (! $disk->exists($this->originalPath)) {
90	            $this->markFailed('Original video file not found on media disk.');
91	            $this->fail(new \RuntimeException('Original video file not found on media disk.'));
92	
93	            return;
94	        }
95	
96	        $localTmp = null;
97	
98	        try {
99	            // Stream the original to a local temp file for FFmpeg processing.
100	            $ext = pathinfo($this->originalPath, PATHINFO_EXTENSION) ?: 'mp4';
101	            $localTmp = tempnam(sys_get_temp_dir(), 'sidest_vid_').'.'.$ext;
102	
103	            $stream = $disk->readStream($this->originalPath);
104	            if (! $stream) {
105	                throw new \RuntimeException('Failed to open read stream for original video.');
106	            }
107	
108	            $dest = fopen($localTmp, 'wb');
109	            if (! $dest) {
110	                fclose($stream);
111	                throw new \RuntimeException('Failed to open local temp file for writing.');
112	            }
113	
114	            stream_copy_to_stream($stream, $dest);
115	            fclose($stream);
116	            fclose($dest);
117	
118	            $service->processVariants(
119	                localOriginalPath: $localTmp,
120	                mediaId: $this->mediaId,
121	                basePath: $this->basePath,
122	            );
123	
124	            Log::info('ProcessVideoVariantsJob: completed.', ['media_id' => $this->mediaId]);
125	        } catch (Throwable $e) {
126	            Log::error('ProcessVideoVariantsJob: processing failed.', [
127	                'media_id' => $this->mediaId,
128	                'error' => $e->getMessage(),
129	                'exception' => get_class($e),
130	            ]);
131	
132	            throw $e;
133	        } finally {
134	            if (isset($localTmp) && file_exists($localTmp)) {
135	                @unlink($localTmp);
136	            }
137	        }
138	    }
139	
140	    public function failed(Throwable $e): void
141	    {
142	        $this->markFailed($e->getMessage());
143	        $this->cleanupR2Artifacts();
144	    }
145	
146	    // Delete the original (and any partial variants) from R2 after terminal failure
147	    // so orphaned files don't accumulate on the media disk indefinitely.
148	    private function cleanupR2Artifacts(): void
149	    {
150	        try {
151	            app(VideoVariantService::class)->deleteVariants($this->mediaId, $this->basePath);
152	        } catch (Throwable $e) {
153	            Log::warning('ProcessVideoVariantsJob: R2 orphan cleanup failed.', [
154	                'media_id' => $this->mediaId,
155	                'error' => $e->getMessage(),
156	            ]);
157	        }
158	    }
159	
160	    private function markFailed(string $reason): void
161	    {
162	        $updated = SiteMedia::query()
163	            ->where('id', $this->mediaId)
164	            ->whereNull('deleted_at')
165	            ->update([
166	                'processing_state' => SiteMedia::PROCESSING_STATE_FAILED,
167	                'processing_error' => $reason,
168	            ]);
169	
170	        if ($updated === 0) {
171	            $siteMedia = SiteMedia::withTrashed()->where('id', $this->mediaId)->first();
172	            Log::info('ProcessVideoVariantsJob: failed-state update skipped.', [
173	                'media_id' => $this->mediaId,
174	                'row_exists' => $siteMedia !== null,
175	                'is_soft_deleted' => $siteMedia?->trashed() ?? false,
176	            ]);
177	        }
178	    }
179	}
