11	/**
12	 * Transcodes a video original into MP4 + HLS variants and a poster image,
13	 * stores all artifacts on the media disk, and persists MediaVariant rows.
14	 *
15	 * Processing order (avoids extra re-encodes):
16	 *   1. FFprobe  – extract metadata + validate duration
17	 *   2. FFmpeg   – encode optimized MP4 (720p)
18	 *   3. FFmpeg   – encode maximized MP4 (1080p)
19	 *   4. FFmpeg   – package HLS segments from each MP4 (stream-copy, no re-encode)
20	 *   5. Build    – write master adaptive HLS playlist
21	 *   6. FFmpeg   – extract poster JPEG at 1s mark
22	 *   7. Upload   – stream all artifacts to media disk
23	 *   8. DB upsert – persist one MediaVariant row per logical artifact
24	 *   9. SiteMedia update – set processing_state, duration_ms, poster_path
25	 *
26	 * Storage layout under the media disk:
27	 *   videos/{proId}/{mediaId}/
28	 *     original_{hash}.{ext}
29	 *     optimized.mp4
30	 *     maximized.mp4
31	 *     hls/
32	 *       optimized/playlist.m3u8  + seg_*.ts
33	 *       maximized/playlist.m3u8  + seg_*.ts
34	 *       adaptive.m3u8             (master playlist)
35	 *     poster.jpg
36	 *
37	 * Requires ffmpeg and ffprobe to be available (configured via config/sidest.php).
38	 */
39	// V2: Transcodes videos to MP4 + HLS via FFmpeg. Feature-flagged (SIDEST_VIDEO_UPLOADS_ENABLED). Uses dedicated redis_video connection.
40	class VideoVariantService
41	{
42	    /* ------------------------------------------------------------------ */
43	    /*  Public API */
44	    /* ------------------------------------------------------------------ */
45	
46	    /**
47	     * Run FFprobe on a local file and return metadata array.
48	     * Throws \RuntimeException if the binary fails.
49	     *
50	     * @return array<string, mixed>
51	     */
52	    public function probe(string $localPath): array
53	    {
54	        $ffprobe = $this->ffprobeBinary();
55	        $cmd = sprintf(
56	            '%s -v quiet -print_format json -show_format -show_streams %s 2>&1',
57	            escapeshellcmd($ffprobe),
58	            escapeshellarg($localPath),
59	        );
60	
61	        $output = $this->runCommand($cmd, $exitCode);
62	
63	        if ($exitCode !== 0) {
64	            throw new \RuntimeException("ffprobe failed (exit {$exitCode}): {$output}");
65	        }
66	
67	        $data = json_decode($output, true);
68	        if (! is_array($data)) {
69	            throw new \RuntimeException('ffprobe returned non-JSON output.');
70	        }
71	
72	        return $data;
73	    }
74	
75	    /**
76	     * Process a video original into all configured artifacts.
77	     *
78	     * @throws \RuntimeException on unrecoverable processing errors
79	     */
80	    public function processVariants(
81	        string $localOriginalPath,
82	        string $mediaId,
83	        string $basePath,
84	    ): void {
85	        Log::info('VideoVariantService: starting', [
86	            'media_id' => $mediaId,
87	            'base_path' => $basePath,
88	        ]);
89	
90	        // --- 1. Probe metadata ---
91	        $probe = $this->probe($localOriginalPath);
92	        $durationMs = $this->extractDurationMs($probe);
93	        $maxDur = (int) config('sidest.video_max_duration_seconds', 300);
94	
95	        if ($durationMs > $maxDur * 1000) {
96	            throw new \RuntimeException(
97	                "Video duration ({$durationMs}ms) exceeds maximum ({$maxDur}s)."
98	            );
99	        }
100	
101	        $variantDefs = (array) config('sidest.video_variants', []);
102	        $tmpDirs = [];
103	
104	        try {
105	            // --- 2 & 3. Encode MP4 variants ---
106	            $mp4Paths = [];
107	            foreach ($variantDefs as $variantKey => $def) {
108	                $tmpMp4 = $this->makeTmpFile("sidest_mp4_{$variantKey}_", '.mp4');
109	                $this->encodeMp4($localOriginalPath, $tmpMp4, $def);
110	                $mp4Paths[$variantKey] = $tmpMp4;
111	            }
112	
113	            // --- 4. Package HLS from each MP4 ---
114	            $hlsDirs = [];
115	            foreach ($mp4Paths as $variantKey => $mp4) {
116	                $tmpHlsDir = sys_get_temp_dir().'/sidest_hls_'.$variantKey.'_'.uniqid();
117	                if (! mkdir($tmpHlsDir, 0755, true)) {
118	                    throw new \RuntimeException("Failed to create HLS temp dir: {$tmpHlsDir}");
119	                }
120	                $tmpDirs[] = $tmpHlsDir;
121	                $this->packageHls($mp4, $tmpHlsDir.'/playlist.m3u8');
122	                $hlsDirs[$variantKey] = $tmpHlsDir;
123	            }
124	
125	            // --- 5. Build adaptive master playlist ---
126	            $adaptiveContent = $this->buildAdaptivePlaylist($variantDefs);
127	
128	            // --- 6. Extract poster ---
129	            $tmpPoster = $this->makeTmpFile('sidest_poster_', '.jpg');
130	            $this->extractPoster($localOriginalPath, $tmpPoster);
131	
132	            // --- 7. Upload all artifacts ---
133	            $disk = $this->disk();
134	            $diskName = $this->resolvedDiskName();
135	
136	            // Upload MP4s
137	            foreach ($mp4Paths as $variantKey => $mp4) {
138	                $remotePath = "{$basePath}/{$variantKey}.mp4";
139	                $stream = fopen($mp4, 'rb');
140	                $disk->put($remotePath, $stream, 'public');
141	                if (is_resource($stream)) {
142	                    fclose($stream);
143	                }
144	
145	                $def = $variantDefs[$variantKey] ?? [];
146	                // Unique key: (media_id, variant_key, artifact_type)
147	                MediaVariant::updateOrCreate(
148	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'mp4'],
149	                    [
150	                        'disk' => $diskName,
151	                        'path' => $remotePath,
152	                        'mime' => 'video/mp4',
153	                        'bitrate_kbps' => (int) ($def['video_bitrate_kbps'] ?? 0) + (int) ($def['audio_bitrate_kbps'] ?? 0),
154	                        'file_size_bytes' => filesize($mp4) ?: null,
155	                        'duration_ms' => $durationMs,
156	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
157	                    ]
158	                );
159	            }
160	
161	            // Upload HLS segments + playlists
162	            foreach ($hlsDirs as $variantKey => $hlsDir) {
163	                $remoteHlsBase = "{$basePath}/hls/{$variantKey}";
164	                foreach (scandir($hlsDir) ?: [] as $file) {
165	                    if ($file === '.' || $file === '..') {
166	                        continue;
167	                    }
168	                    $localFile = "{$hlsDir}/{$file}";
169	                    $remotePath = "{$remoteHlsBase}/{$file}";
170	                    $mime = str_ends_with($file, '.m3u8') ? 'application/vnd.apple.mpegurl' : 'video/mp2t';
171	                    $stream = fopen($localFile, 'rb');
172	                    $disk->put($remotePath, $stream, ['visibility' => 'public', 'ContentType' => $mime]);
173	                    if (is_resource($stream)) {
174	                        fclose($stream);
175	                    }
176	                }
177	
178	                $playlistPath = "{$remoteHlsBase}/playlist.m3u8";
179	                $def = $variantDefs[$variantKey] ?? [];
180	                MediaVariant::updateOrCreate(
181	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'hls_playlist'],
182	                    [
183	                        'disk' => $diskName,
184	                        'path' => $playlistPath,
185	                        'mime' => 'application/vnd.apple.mpegurl',
186	                        'duration_ms' => $durationMs,
187	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
188	                    ]
189	                );
190	            }
191	
192	            // Upload adaptive master playlist
193	            $adaptiveRemotePath = "{$basePath}/hls/adaptive.m3u8";
194	            $disk->put($adaptiveRemotePath, $adaptiveContent, [
195	                'visibility' => 'public',
196	                'ContentType' => 'application/vnd.apple.mpegurl',
197	            ]);
198	
199	            MediaVariant::updateOrCreate(
200	                ['media_id' => $mediaId, 'variant_key' => 'adaptive', 'artifact_type' => 'hls_playlist'],
201	                [
202	                    'disk' => $diskName,
203	                    'path' => $adaptiveRemotePath,
204	                    'mime' => 'application/vnd.apple.mpegurl',
205	                ]
206	            );
207	
208	            // Upload poster
209	            $posterRemotePath = "{$basePath}/poster.jpg";
210	            $stream = fopen($tmpPoster, 'rb');
211	            $disk->put($posterRemotePath, $stream, ['visibility' => 'public', 'ContentType' => 'image/jpeg']);
212	            if (is_resource($stream)) {
213	                fclose($stream);
214	            }
215	
216	            MediaVariant::updateOrCreate(
217	                ['media_id' => $mediaId, 'variant_key' => 'poster', 'artifact_type' => 'poster'],
218	                [
219	                    'disk' => $diskName,
220	                    'path' => $posterRemotePath,
221	                    'mime' => 'image/jpeg',
222	                    'file_size_bytes' => filesize($tmpPoster) ?: null,
223	                ]
224	            );
225	
226	            // --- 8. Update SiteMedia ---
227	            SiteMedia::query()
228	                ->where('id', $mediaId)
229	                ->whereNull('deleted_at')
230	                ->update([
231	                    'processing_state' => SiteMedia::PROCESSING_STATE_READY,
232	                    'processing_error' => null,
233	                    'duration_ms' => $durationMs,
234	                    'poster_path' => $posterRemotePath,
235	                ]);
236	
237	            Log::info('VideoVariantService: completed', [
238	                'media_id' => $mediaId,
239	                'duration_ms' => $durationMs,
240	            ]);
241	        } finally {
242	            // Cleanup temp files and dirs
243	            foreach ($mp4Paths ?? [] as $mp4) {
244	                if (file_exists($mp4)) {
245	                    @unlink($mp4);
246	                }
247	            }
248	            if (isset($tmpPoster) && file_exists($tmpPoster)) {
249	                @unlink($tmpPoster);
250	            }
251	            foreach ($tmpDirs as $dir) {
252	                $this->removeDir($dir);
253	            }
254	        }
255	    }
256	
257	    /**
258	     * Delete all media_variants DB rows and all files under $basePath on disk.
259	     * Called by DeleteMediaArtifactsJob (async) for video cleanup.
260	     */
261	    public function deleteVariants(string $mediaId, string $basePath): void
262	    {
263	        $disk = $this->disk();
264	        $basePrefix = $this->normalizeVideoCleanupBasePath($basePath);
265	
266	        // Delete all files under the normalized video prefix.
267	        try {
268	            $files = $disk->allFiles($basePrefix);
269	        } catch (\Throwable $e) {
270	            throw new \RuntimeException(
271	                "Failed to list video artifacts for cleanup at [{$basePrefix}].",
272	                0,
273	                $e
274	            );
275	        }
276	
277	        foreach ($files as $file) {
278	            try {
279	                $deleted = $disk->delete($file);
280	            } catch (\Throwable $e) {
281	                throw new \RuntimeException(
282	                    "Failed to delete video artifact [{$file}].",
283	                    0,
284	                    $e
285	                );
286	            }
287	
288	            if ($deleted === false) {
289	                throw new \RuntimeException("Failed to delete video artifact [{$file}].");
290	            }
291	        }
292	
293	        // Delete DB rows only after storage cleanup succeeds.
294	        MediaVariant::where('media_id', $mediaId)->delete();
295	    }
296	
297	    /**
298	     * Resolve the effective media disk name.
299	     * Mirrors the logic in ImageVariantService for consistency.
300	     */
301	    public function resolvedDiskName(): string
302	    {
303	        return $this->diskName();
304	    }
305	
306	    /* ------------------------------------------------------------------ */
307	    /*  Private helpers */
308	    /* ------------------------------------------------------------------ */
309	
310	    private function encodeMp4(string $input, string $output, array $def): void
311	    {
312	        $ffmpeg = $this->ffmpegBinary();
313	        $resolution = (string) ($def['resolution'] ?? '1280x720');
314	        [$width, $height] = array_map('intval', explode('x', $resolution, 2));
315	        $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
316	        $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
317	
318	        // Scale to fit within resolution bounds while maintaining aspect ratio.
319	        // The scale filter uses -2 to keep dimensions divisible by 2 (required by libx264).
320	        $scaleFilter = "scale='if(gt(iw,{$width}),{$width},-2)':'if(gt(ih,{$height}),{$height},-2)'";
321	
322	        $cmd = sprintf(
323	            '%s -y -i %s -vf %s -c:v libx264 -b:v %dk -maxrate %dk -bufsize %dk '
324	            .'-profile:v main -level 4.0 -movflags +faststart '
325	            .'-c:a aac -b:a %dk -ar 44100 %s 2>&1',
326	            escapeshellcmd($ffmpeg),
327	            escapeshellarg($input),
328	            escapeshellarg($scaleFilter),
329	            $videoBitrate,
330	            (int) ($videoBitrate * 1.5),
331	            (int) ($videoBitrate * 2),
332	            $audioBitrate,
333	            escapeshellarg($output),
334	        );
335	
336	        $output_str = $this->runCommand($cmd, $exitCode);
337	
338	        if ($exitCode !== 0) {
339	            throw new \RuntimeException("ffmpeg MP4 encoding failed (exit {$exitCode}): {$output_str}");
340	        }
341	    }
342	
343	    private function packageHls(string $mp4Input, string $playlistOutput): void
344	    {
345	        $ffmpeg = $this->ffmpegBinary();
346	        $outputDir = dirname($playlistOutput);
347	        $segmentPattern = $outputDir.'/seg_%03d.ts';
348	
349	        $cmd = sprintf(
350	            '%s -y -i %s -c copy -f hls -hls_time 6 -hls_playlist_type vod '
351	            .'-hls_segment_filename %s %s 2>&1',
352	            escapeshellcmd($ffmpeg),
353	            escapeshellarg($mp4Input),
354	            escapeshellarg($segmentPattern),
355	            escapeshellarg($playlistOutput),
356	        );
357	
358	        $output = $this->runCommand($cmd, $exitCode);
359	
360	        if ($exitCode !== 0) {
361	            throw new \RuntimeException("ffmpeg HLS packaging failed (exit {$exitCode}): {$output}");
362	        }
363	    }
364	
365	    private function extractPoster(string $input, string $output): void
366	    {
367	        $ffmpeg = $this->ffmpegBinary();
368	
369	        $cmd = sprintf(
370	            '%s -y -i %s -ss 00:00:01 -frames:v 1 -q:v 3 %s 2>&1',
371	            escapeshellcmd($ffmpeg),
372	            escapeshellarg($input),
373	            escapeshellarg($output),
374	        );
375	
376	        $outputStr = $this->runCommand($cmd, $exitCode);
377	
378	        if ($exitCode !== 0 || ! file_exists($output)) {
379	            // Non-fatal: try frame at 0s as fallback
380	            $cmd2 = sprintf(
381	                '%s -y -i %s -frames:v 1 -q:v 3 %s 2>&1',
382	                escapeshellcmd($ffmpeg),
383	                escapeshellarg($input),
384	                escapeshellarg($output),
385	            );
386	            $this->runCommand($cmd2, $exitCode2);
387	
388	            if ($exitCode2 !== 0 || ! file_exists($output)) {
389	                Log::warning('VideoVariantService: could not extract poster frame.', [
390	                    'error' => $outputStr,
391	                ]);
392	                // Create a 1-byte placeholder so downstream code doesn't fail
393	                file_put_contents($output, '');
394	            }
395	        }
396	    }
397	
398	    /**
399	     * Build the adaptive (master) HLS playlist content.
400	     *
401	     * @param  array<string, array<string, mixed>>  $variantDefs
402	     */
403	    private function buildAdaptivePlaylist(array $variantDefs): string
404	    {
405	        $lines = ['#EXTM3U'];
406	
407	        foreach ($variantDefs as $variantKey => $def) {
408	            $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
409	            $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
410	            $bandwidth = ($videoBitrate + $audioBitrate) * 1000;
411	            $resolution = strtoupper((string) ($def['resolution'] ?? '1280x720'));
412	
413	            $lines[] = "#EXT-X-STREAM-INF:BANDWIDTH={$bandwidth},RESOLUTION={$resolution}";
414	            $lines[] = "{$variantKey}/playlist.m3u8";
415	        }
416	
417	        return implode("\n", $lines)."\n";
418	    }
419	
420	    private function extractDurationMs(array $probe): int
421	    {
422	        $duration = $probe['format']['duration'] ?? null;
423	        if ($duration === null) {
424	            // Fall back to the first video stream
425	            foreach ($probe['streams'] ?? [] as $stream) {
426	                if (($stream['codec_type'] ?? '') === 'video' && isset($stream['duration'])) {
427	                    $duration = $stream['duration'];
428	                    break;
429	                }
430	            }
431	        }
432	
433	        return $duration !== null ? (int) round((float) $duration * 1000) : 0;
434	    }
435	
436	    private function makeTmpFile(string $prefix, string $suffix): string
437	    {
438	        $path = tempnam(sys_get_temp_dir(), $prefix);
439	        if (! $path) {
440	            throw new \RuntimeException("Failed to create temp file ({$prefix}).");
441	        }
442	
443	        // Rename to add the desired extension so FFmpeg knows the container.
444	        $withExt = $path.$suffix;
445	        rename($path, $withExt);
446	
447	        return $withExt;
448	    }
449	
450	    /**
451	     * Run a pre-escaped shell command via Symfony Process and return its output.
452	     * $exitCode is set by reference.
453	     *
454	     * All arguments in $cmd must be escaped by the caller via
455	     * escapeshellcmd()/escapeshellarg() before this method is called.
456	     * No timeout is applied — video encoding can be arbitrarily long.
457	     */
458	    private function runCommand(string $cmd, ?int &$exitCode = null): string
459	    {
460	        $process = Process::fromShellCommandline($cmd);
461	        $process->setTimeout(null);
462	        $process->run();
463	
464	        $exitCode = $process->getExitCode() ?? 0;
465	
466	        // Callers append 2>&1, so all output (including stderr) is in stdout
467	        return $process->getOutput();
468	    }
469	
470	    private function removeDir(string $dir): void
471	    {
472	        if (! is_dir($dir)) {
473	            return;
474	        }
475	
476	        foreach (scandir($dir) ?: [] as $file) {
477	            if ($file === '.' || $file === '..') {
478	                continue;
479	            }
480	            $path = "{$dir}/{$file}";
481	            is_dir($path) ? $this->removeDir($path) : @unlink($path);
482	        }
483	
484	        @rmdir($dir);
485	    }
486	
487	    /**
488	     * Legacy jobs may pass the original file path instead of the media directory.
489	     * Normalize to the directory prefix expected by allFiles().
490	     */
491	    private function normalizeVideoCleanupBasePath(string $basePath): string
492	    {
493	        $normalized = trim($basePath);
494	        if ($normalized === '') {
495	            throw new \RuntimeException('Video cleanup base path cannot be empty.');
496	        }
497	
498	        $leaf = basename($normalized);
499	        if (str_contains($leaf, '.')) {
500	            $normalized = dirname($normalized);
501	        }
502	
503	        $normalized = trim($normalized, '/');
504	        if ($normalized === '' || $normalized === '.') {
505	            throw new \RuntimeException('Video cleanup base path resolved to an invalid directory.');
506	        }
507	
508	        return $normalized;
509	    }
510	
511	    private function diskName(): string
512	    {
513	        $configured = (string) config('sidest.media_disk', 'media');
514	
515	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
516	        // but injects platform env vars directly into the process environment at runtime,
517	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
518	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
519	        if (is_string($explicit) && trim($explicit) !== '') {
520	            return $configured;
521	        }
522	
523	        if ($configured === 'media') {
524	            $default = (string) config('filesystems.default', 'local');
525	            $defaultConfig = config("filesystems.disks.{$default}");
526	
527	            if (
528	                $default !== '' &&
529	                $default !== 'local' &&
530	                $default !== 'media' &&
531	                is_array($defaultConfig) &&
532	                (($defaultConfig['driver'] ?? null) === 's3')
533	            ) {
534	                return $default;
535	            }
536	        }
537	
538	        return $configured;
539	    }
540	
541	    private function disk(): \Illuminate\Contracts\Filesystem\Filesystem
542	    {
543	        return Storage::disk($this->diskName());
544	    }
545	
546	    private function ffmpegBinary(): string
547	    {
548	        return (string) config('sidest.ffmpeg_binary', 'ffmpeg');
549	    }
550	
551	    private function ffprobeBinary(): string
552	    {
553	        return (string) config('sidest.ffprobe_binary', 'ffprobe');
554	    }
555	}
