257	    /**
258	     * Delete all media_variants DB rows and all files under $basePath on disk.
259	     * Called by DeleteMediaArtifactsJob (async) for video cleanup.
260	     */
261	    public function deleteVariants(string $mediaId, string $basePath): void
262	    {
263	        $disk = $this->disk();
264	        $basePrefix = $this->normalizeVideoCleanupBasePath($basePath);
265	
266	        // Delete all files under the normalized video prefix.
267	        try {
268	            $files = $disk->allFiles($basePrefix);
269	        } catch (\Throwable $e) {
270	            throw new \RuntimeException(
271	                "Failed to list video artifacts for cleanup at [{$basePrefix}].",
272	                0,
273	                $e
274	            );
275	        }
276	
277	        foreach ($files as $file) {
278	            try {
279	                $deleted = $disk->delete($file);
280	            } catch (\Throwable $e) {
