40	    /**
41	     * Upload an image or video to a pool (gallery or content).
42	     *
43	     * Accepts exactly one of: `image` (JPEG/PNG/WebP) or `video` (MP4/MOV/WebM).
44	     * Returns immediately; processing runs async on the appropriate queue.
45	     *
46	     * POST /api/uploads
47	     *   { pool: gallery|content, image?: <file>, video?: <file>, alt_text?: string }
48	     */
49	    public function upload(UploadImageRequest $request): JsonResponse
50	    {
51	        $pro = $this->currentProfessional($request);
52	        $pro->loadMissing('site');
53	        $site = $this->currentSite($pro);
54	
55	        $pool = $request->validated('pool');
56	        $isVideo = $request->hasFile('video');
57	        $file = $isVideo ? $request->file('video') : $request->file('image');
58	        $mediaType = $isVideo ? SiteMedia::MEDIA_TYPE_VIDEO : SiteMedia::MEDIA_TYPE_IMAGE;
59	
60	        Log::info('Media upload started', [
61	            'pro_id' => $pro->id,
62	            'site_id' => $site->id,
63	            'pool' => $pool,
64	            'media_type' => $mediaType,
65	            'file_size_kb' => $file->getSize() / 1024,
66	        ]);
67	
68	        // Pool limit is shared across media types (images + videos count toward the same cap).
69	        $maxItems = (int) config("sidest.image_pools.{$pool}.max", 5);
70	
71	        $activeCount = SiteMedia::query()
72	            ->where('site_id', $site->id)
73	            ->where('pool', $pool)
74	            ->where('is_active', true)
75	            ->count();
76	
77	        if ($activeCount >= $maxItems) {
78	            return $this->error(
79	                ucfirst($pool)." media limit reached (max {$maxItems}).", 422
80	            );
81	        }
82	
83	        // --- Create SiteMedia row (with advisory lock for race safety) ---
84	        $media = DB::transaction(function () use ($site, $pool, $maxItems, $request, $mediaType, $file) {
85	            if (DB::getDriverName() === 'pgsql') {
86	                DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-images:{$site->id}"]);
87	            }
88	
89	            $siteImages = SiteMedia::query()
90	                ->where('site_id', $site->id)
91	                ->lockForUpdate()
92	                ->get(['id', 'pool', 'sort_order', 'is_active']);
93	
94	            $activeCount = $siteImages
95	                ->where('pool', $pool)
96	                ->where('is_active', true)
97	                ->count();
98	
99	            if ($activeCount >= $maxItems) {
100	                abort(422, ucfirst($pool)." media limit reached (max {$maxItems}).");
101	            }
102	
103	            $maxSort = $siteImages->max('sort_order');
104	
105	            $media = SiteMedia::create([
106	                'site_id' => $site->id,
107	                'pool' => $pool,
108	                'path' => '',
109	                'alt_text' => $request->validated('alt_text'),
110	                'caption' => $this->normaliseOptionalString($request->validated('caption')),
111	                'sort_order' => is_null($maxSort) ? 0 : ((int) $maxSort + 1),
112	                'is_active' => true,
113	                'media_type' => $mediaType,
114	                'processing_state' => SiteMedia::PROCESSING_STATE_PENDING,
115	                'original_mime' => $file->getMimeType(),
116	                'original_size_bytes' => $file->getSize(),
117	            ]);
118	
119	            Log::info('SiteMedia row created', ['media_id' => $media->id, 'media_type' => $mediaType]);
120	
121	            return $media;
122	        });
123	
124	        // --- Store original on media disk ---
125	        $basePath = $isVideo
126	            ? "videos/{$pro->id}/{$media->id}"
127	            : "images/{$pro->id}/{$media->id}";
128	
129	        try {
130	            $mediaDisk = $this->mediaService->resolvedDiskName();
131	
132	            Log::info('Storing original to media disk', [
133	                'media_id' => $media->id,
134	                'base_path' => $basePath,
135	                'media_disk' => $mediaDisk,
136	            ]);
137	
138	            if ($isVideo) {
139	                // Stream large video files to avoid loading full content into memory.
140	                $ext = $this->mediaService->safeExtension($file->getClientOriginalExtension() ?? '', 'mp4');
141	                $hash = substr(hash_file('sha256', $file->getRealPath()), 0, 16);
142	                $path = "{$basePath}/original_{$hash}.{$ext}";
143	                $stream = fopen($file->getRealPath(), 'rb');
144	                Storage::disk($mediaDisk)->put($path, $stream, 'public');
145	                if (is_resource($stream)) {
146	                    fclose($stream);
147	                }
148	                $originalPath = $path;
149	            } else {
150	                $originalPath = $this->mediaService->storeOriginal($file, $basePath);
151	            }
152	
153	            Log::info('Original stored successfully', ['media_id' => $media->id, 'path' => $originalPath]);
154	        } catch (\Exception $e) {
155	            Log::error('Failed to store original', [
156	                'media_id' => $media->id,
157	                'error' => $e->getMessage(),
158	            ]);
159	            $media->delete();
160	
161	            return $this->error('Failed to store file: '.$e->getMessage(), 500);
162	        }
163	
164	        $media->update(['path' => $originalPath]);
165	
166	        // --- Dispatch processing job ---
167	        if ($isVideo) {
168	            try {
169	                $this->dispatchVideoJob($media->id, $originalPath, $basePath);
170	            } catch (Throwable $e) {
171	                Log::error('Video upload dispatch failed; rolling back media item.', [
172	                    'site_id' => $site->id,
173	                    'media_id' => $media->id,
174	                    'pool' => $pool,
175	                    'error' => $e->getMessage(),
176	                    'exception' => get_class($e),
177	                ]);
178	
179	                $mediaDisk = $this->mediaService->resolvedDiskName();
180	                try {
181	                    Storage::disk($mediaDisk)->delete($originalPath);
182	                } catch (Throwable $cleanupError) {
183	                    Log::warning('Failed to cleanup original video after dispatch failure.', [
184	                        'site_id' => $site->id,
185	                        'media_id' => $media->id,
186	                        'pool' => $pool,
187	                        'path' => $originalPath,
188	                        'media_disk' => $mediaDisk,
189	                        'error' => $cleanupError->getMessage(),
190	                    ]);
191	                }
192	
193	                $media->delete();
194	                app(SiteCacheService::class)->invalidateSite($site);
195	
196	                return $this->error(
197	                    'Video processing is temporarily unavailable. Please try again.',
198	                    503
199	                );
200	            }
201	        } else {
202	            $this->dispatchImageJob($media->id, $originalPath, $basePath);
203	        }
204	
205	        app(SiteCacheService::class)->invalidateSite($site);
206	
207	        // Refresh model state (sync mode may have updated processing_state to 'ready').
208	        $media->refresh();
209	        $media->load('mediaVariants');
210	        $payload = $this->buildMediaPayload($media, includeVariants: true);
211	
212	        return $this->success($payload, 201);
213	    }
