368	    /**
369	     * Delete a media item and all its artifacts.
370	     *
371	     * Images are cleaned up synchronously (small number of files).
372	     * Videos are cleaned up asynchronously via DeleteMediaArtifactsJob (many HLS segments).
373	     *
374	     * DELETE /api/images/{image}
375	     */
376	    public function destroy(Request $request, SiteMedia $image): JsonResponse
377	    {
378	        $pro = $this->currentProfessional($request);
379	        $pro->loadMissing('site');
380	        $site = $this->currentSite($pro);
381	
382	        abort_unless($image->site_id === $site->id, 404);
383	
384	        if ($image->media_type === SiteMedia::MEDIA_TYPE_VIDEO) {
385	            // Dispatch async cleanup – video has many HLS segment files.
386	            $basePath = is_string($image->path) && trim($image->path) !== ''
387	                ? dirname($image->path)
388	                : "videos/{$pro->id}/{$image->id}";
389	
390	            DeleteMediaArtifactsJob::dispatch($image->id, $basePath, $image->pool);
391	        } else {
392	            // Synchronous cleanup for images (only 2–3 variant files).
393	            $this->mediaService->deleteVariants($image->id, $image->path);
394	        }
395	
396	        $image->delete();
397	
398	        if ($this->shouldRememberConfirmationPreference($request)) {
399	            app(ConfirmationPreferenceService::class)->enableForProfessional(
400	                (string) $pro->id,
401	                ConfirmationPreferenceService::ACTION_DELETE_MEDIA
402	            );
403	        }
404	
405	        app(SiteCacheService::class)->invalidateSite($site);
406	
407	        return $this->success(['deleted' => true]);
408	    }
