609	
610	        try {
611	            ProcessImageVariantsJob::dispatch(
612	                originalPath: $originalPath,
613	                imageId: $imageId,
614	                basePath: $basePath,
615	            );
616	        } catch (Throwable $e) {
617	            Log::error('Queue dispatch failed for image; trying synchronous fallback.', [
618	                'image_id' => $imageId, 'error' => $e->getMessage(),
619	            ]);
620	            try {
621	                ProcessImageVariantsJob::dispatchSync(
622	                    originalPath: $originalPath,
