218	     * GET /api/images
219	     *   ?pool=gallery|content          optional pool filter
220	     *   ?media_type=image|video|all    default: image (backward-compatible)
221	     *   ?ids[]=uuid,...                optional: return only specific media items (for polling)
222	     */
223	    public function index(): JsonResponse
224	    {
225	        $pro = $this->currentProfessional(request());
226	        $pro->loadMissing('site');
227	        $site = $this->currentSite($pro);
228	
229	        $rawMediaType = strtolower(trim((string) request()->input('media_type', 'image')));
230	        $mediaTypeFilter = in_array($rawMediaType, ['image', 'video', 'all'], true) ? $rawMediaType : 'image';
231	
232	        $query = SiteMedia::query()
233	            ->where('site_id', $site->id)
234	            ->where('is_active', true)
235	            ->orderBy('pool')
236	            ->orderBy('sort_order')
237	            ->orderBy('created_at');
238	
239	        if ($mediaTypeFilter !== 'all') {
240	            $query->where('media_type', $mediaTypeFilter);
241	        }
242	
243	        if (request()->has('pool')) {
244	            $pool = strtolower(trim(request()->input('pool')));
245	            if (in_array($pool, ['gallery', 'content'], true)) {
246	                $query->where('pool', $pool);
247	            }
248	        }
249	
250	        // Efficient polling: return only the requested IDs.
251	        if (request()->has('ids')) {
252	            $ids = array_filter((array) request()->input('ids'), fn ($id) => is_string($id) && Str::isUuid($id));
253	            if (! empty($ids)) {
