258	        $query->with('mediaVariants');
259	
260	        $items = $query->get()->map(fn (SiteMedia $item) => $this->buildMediaPayload($item, includeVariants: true));
261	
262	        return $this->success([
263	            'images' => $items,
264	            'limits' => [
265	                'gallery' => config('sidest.image_pools.gallery.max', 5),
266	                'content' => config('sidest.image_pools.content.max', 5),
267	            ],
268	        ]);
