275	     *   { pool: gallery|content, media_type?: image|video, ids: [uuid, ...] }
276	     *
277	     * Scope is pool + optional media_type:
278	     *   - `media_type` provided → reorder only items of that type (legacy
279	     *     behaviour; kept so Content panel's image-only + video-only reorders
280	     *     still work).
281	     *   - `media_type` omitted → reorder the *entire pool* across media types.
282	     *     Required for the unified affiliate gallery grid where photos and
283	     *     videos share one ordered list of 6 slots.
284	     */
285	    public function reorder(ReorderPoolImagesRequest $request): JsonResponse
286	    {
287	        $pro = $this->currentProfessional($request);
288	        $pro->loadMissing('site');
289	        $site = $this->currentSite($pro);
290	
291	        $pool = $request->validated('pool');
292	        // null here = mixed-type reorder (unified grid). Don't default to
293	        // 'image' — that silently drops video ids and corrupts the order.
294	        $mediaType = $request->validated('media_type');
295	        $ids = array_values(array_unique($request->validated('ids') ?? []));
296	
297	        DB::transaction(function () use ($site, $pool, $mediaType, $ids) {
298	            if (DB::getDriverName() === 'pgsql') {
299	                DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-images:{$site->id}"]);
300	            }
301	
302	            $siteImages = SiteMedia::query()
303	                ->where('site_id', $site->id)
304	                ->lockForUpdate()
305	                ->orderBy('sort_order')
306	                ->orderBy('created_at')
307	                ->get(['id', 'pool', 'media_type', 'sort_order', 'is_active']);
308	
309	            $targetImages = $siteImages
310	                ->where('is_active', true)
311	                ->where('pool', $pool)
312	                ->when($mediaType !== null, fn ($c) => $c->where('media_type', $mediaType))
313	                ->values();
314	
315	            if ($targetImages->isEmpty()) {
316	                abort(422, 'No active media found in this pool.');
317	            }
318	
319	            $targetIds = $targetImages->pluck('id')->all();
320	            $targetSet = array_flip($targetIds);
321	
322	            foreach ($ids as $id) {
323	                if (! isset($targetSet[$id])) {
324	                    abort(422, 'One or more media items are invalid.');
325	                }
326	            }
327	
328	            $remainingTargetIds = array_values(array_diff($targetIds, $ids));
329	            $reorderedTargetIds = array_merge($ids, $remainingTargetIds);
330	
331	            $finalIds = $siteImages->pluck('id')->all();
332	            $targetPositions = [];
333	
334	            foreach ($siteImages as $index => $image) {
335	                $matchesPool = $image->is_active && $image->pool === $pool;
336	                $matchesType = $mediaType === null || $image->media_type === $mediaType;
337	                if ($matchesPool && $matchesType) {
338	                    $targetPositions[] = $index;
339	                }
340	            }
341	
342	            foreach ($targetPositions as $index => $position) {
343	                $finalIds[$position] = $reorderedTargetIds[$index];
344	            }
345	
346	            $offset = $siteImages->count() + 1000;
347	
348	            foreach ($finalIds as $index => $id) {
349	                SiteMedia::query()
350	                    ->where('site_id', $site->id)
351	                    ->where('id', $id)
352	                    ->update(['sort_order' => $offset + $index]);
353	            }
354	
355	            foreach ($finalIds as $index => $id) {
356	                SiteMedia::query()
357	                    ->where('site_id', $site->id)
358	                    ->where('id', $id)
359	                    ->update(['sort_order' => $index]);
360	            }
361	        });
362	
363	        app(SiteCacheService::class)->invalidateSite($site);
364	
365	        return $this->success(['ok' => true]);
366	    }
