538	    private function storeBrandDesignImage(
539	        \App\Models\Core\Professional\Professional $pro,
540	        \App\Models\Core\Site\Site $site,
541	        \Illuminate\Http\UploadedFile $file,
542	        string $label,
543	    ): JsonResponse {
544	        // $label is one of: 'logo_full', 'logo_square', or 'placeholder'.
545	        // The brand-logo and brand-placeholder routes both funnel through here
546	        // so BrandDesignMediaService is the only writer.
547	        try {
548	            $media = match ($label) {
549	                'logo_full' => $this->brandDesign->upsertLogoFromUploadedFile($site, $pro->id, $file, 'full'),
550	                'logo_square' => $this->brandDesign->upsertLogoFromUploadedFile($site, $pro->id, $file, 'square'),
551	                'placeholder' => $this->brandDesign->addPlaceholder($site, $pro->id, $file),
552	                default => throw new \InvalidArgumentException("Unknown brand design label: {$label}"),
553	            };
554	        } catch (\App\Services\Media\PlaceholderLimitExceededException $e) {
555	            return $this->error($e->getMessage(), 422);
556	        } catch (\Throwable $e) {
557	            Log::error("Brand {$label} upload failed.", [
558	                'site_id' => $site->id,
559	                'error' => $e->getMessage(),
560	            ]);
561	
562	            return $this->error('Failed to upload brand design asset.', 500);
563	        }
564	
565	        $media->load('mediaVariants');
566	        $isReady = $media->processing_state === SiteMedia::PROCESSING_STATE_READY;
567	        $variants = $isReady ? $media->variantUrls() : [];
568	        $mediaDisk = $this->mediaService->resolvedDiskName();
569	
570	        return $this->success([
571	            'path' => $media->path,
572	            'url' => $variants['optimized'] ?? Storage::disk($mediaDisk)->url($media->path),
573	            'name' => $file->getClientOriginalName(),
574	            'disk' => $mediaDisk,
575	            'site_id' => $site->id,
576	            'media_id' => $media->id,
577	            'media_purpose' => $media->purpose,
578	            'sort_order' => (int) $media->sort_order,
